import {growthReady} from './growth.js?v=simulation15';
import {FARMS,ensureFarms,buyFarm,startFarm,collectFarm} from './regional-farms.js?v=simulation15';import {WEATHER,ensureWeather,weatherType,selectWeather} from './weather.js?v=landscape13';
const items=o=>Object.entries(o).map(([k,v])=>v+' '+k).join(' + ');
export function installRegionalUI({state,save,modal,toast,walk,work,stationFor,preview,scenic,modelStatus=()=>''}){
 const footer='<div class="choice county-footer"><button onclick="openRegionalMap()">Regional atlas</button><button onclick="openCountyMap()">Home county</button><button onclick="openWeather()">Sky & weather</button></div>';
 window.openRegionalMap=()=>{const own=ensureFarms(state).owned;modal('<span class="service-tag">MEADOW REGIONS</span><h2>Beyond the home county.</h2><p>Four larger farm estates sit along the regional roads. Your original farm stays where it is, with all its animals, horses and businesses.</p><div class="regional-atlas">'+FARMS.map((p,i)=>'<button class="regional-estate estate-'+i+'" onclick="openRegionalFarm(\''+p.id+'\')"><small>'+p.region+'</small><b>'+p.name+'</b><span>'+(own[p.id]?'Owned':p.price+' farm coins')+'</span></button>').join('')+'<button class="regional-home" onclick="openCountyMap()">Home county<br>Village · Depot · Racing</button></div><p>Playable region: 508 × 440 game units. Distant districts use simpler scenery and build detail near the camera. Farm ownership and production are saved in this browser.</p><p class="asset-note">This is a local regional map. Multiplayer still needs server-owned parcels, accounts and synchronised players; buying here does not reserve land on a multiplayer server.</p>'+footer);};
 window.openRegionalFarm=id=>{const p=FARMS.find(p=>p.id===id);if(!p)return;const r=ensureFarms(state).owned[id],descriptions={crop:'A working crop estate with a farmhouse, machinery shed and broad maize beds.',orchard:'An established orchard estate with fruit trees, packing space and a farmhouse.',dairy:'A dairy estate with a farmhouse, cattle barn and resident animated cattle.',boarding:'A boarding estate with stables, turnout space and resident animated horses. These business horses are separate from your racing stable.'};modal('<span class="service-tag">'+p.region.toUpperCase()+'</span><h2>'+p.name+'</h2><p>'+descriptions[p.kind]+'</p><p><b>'+items(p.input)+' → '+items(p.output)+'</b><br>'+p.days+' farm day'+(p.days===1?'':'s')+' per production cycle. No automatic rent or spending.</p><div class="choice"><button onclick="previewRegionalFarm(\''+id+'\')">View estate in 3D</button><button onclick="visitRegionalFarm(\''+id+'\')">Walk to entrance</button></div><p>Road entrance: '+p.approach.x+', '+p.approach.z+'. You can drive there, park, then use the farm actions.</p>'+(r?'<p>Owned since farm day '+r.boughtDay+' · '+r.cycles+' cycles collected</p>'+(r.job?'<p>'+(growthReady(r.job,state.day)?'Production ready.':'Ready on farm day '+r.job.readyDay)+'</p><button class="primary" onclick="regionalFarmAction(\''+id+'\',\'collect\')" '+(!growthReady(r.job,state.day)?'disabled':'')+'>Walk here & collect</button>':'<button class="primary" onclick="regionalFarmAction(\''+id+'\',\'start\')">Walk here & start cycle</button>'):'<p>Buy this complete farm for <b>'+p.price+' available farm coins</b>.</p><button class="primary" onclick="regionalFarmAction(\''+id+'\',\'buy\')">Walk here & buy farm</button>')+'<p class="asset-note">'+modelStatus(id)+'</p>'+footer);};
 window.previewRegionalFarm=id=>{const p=FARMS.find(p=>p.id===id);if(p){document.querySelector('dialog').close();preview(p);}};
 window.visitRegionalFarm=id=>{const p=FARMS.find(p=>p.id===id);if(!p)return;document.querySelector('dialog').close();walk(p.approach.x,p.approach.z,'Walk to '+p.name,()=>window.openRegionalFarm(id));};
 window.regionalFarmAction=(id,action)=>{const p=FARMS.find(p=>p.id===id),fn={buy:buyFarm,start:startFarm,collect:collectFarm}[action];if(!p||!fn)return;work(stationFor(id),()=>{try{fn(state,id);save();toast(p.name+': '+({buy:'farm purchased',start:'production started',collect:'production collected'}[action])+'.');}catch(e){toast(e.message);}},({buy:'Buy ',start:'Start ',collect:'Collect from '}[action])+p.name);};
 window.openWeather=()=>{const w=ensureWeather(state);modal('<span class="service-tag">THE SKY ABOVE MEADOW</span><h2>Skies that change.</h2><p>Current forecast: <b id="weather-current">'+WEATHER[weatherType(state)].name+'</b>. Automatic weather changes with the farm day. Clouds drift continuously; showers and storms bring rain and wind.</p><label>Weather pattern<select id="weather-pattern" onchange="setFarmWeather(this.value)"><option value="auto" '+(w.mode==='auto'?'selected':'')+'>Automatic forecast</option>'+Object.entries(WEATHER).map(([id,p])=>'<option value="'+id+'" '+(w.mode===id?'selected':'')+'>'+p.name+'</option>').join('')+'</select></label><p>Weather is visual in this release; it does not unexpectedly change existing crop timers, costs or horse statistics.</p><div class="choice"><button onclick="scenicFarmView()">Scenic horizon view</button><button onclick="home();document.querySelector(\'dialog\').close()">Return to farmer</button></div>'+footer);};
 window.setFarmWeather=mode=>{try{selectWeather(state,mode);save();const current=document.querySelector('#weather-current');if(current)current.textContent=WEATHER[weatherType(state)].name;toast(mode==='auto'?'Automatic forecast enabled.':WEATHER[mode].name+' selected.');}catch(e){toast(e.message);}};
 window.scenicFarmView=()=>{document.querySelector('dialog').close();scenic();};
}
